import 'package:isar/isar.dart';

import '../../domain/entities/decision_enums.dart';

part 'isar_ai_insight.g.dart';

/// Mirrors AI_INSIGHTS. Insights are generated by the backend (Gemini), so the
/// app never edits one and this collection has no sync status. Instead, a
/// record is saved as [InsightStatus.processing] when the request is sent, and
/// becomes complete or failed when it ends. This guards against duplicate
/// requests, even across an app restart.
@collection
class IsarAiInsight {
  Id localId = Isar.autoIncrement;

  // Not unique: null while processing, and Isar counts null as a value.
  @Index()
  String? serverId; // Set when the server returns the finished insight

  @Index(composite: [CompositeIndex('triggerContext')])
  late int decisionLocalId;
  late String decisionServerId; // The decision must be synced before a request

  @Enumerated(EnumType.name)
  late TriggerContext triggerContext;

  @Index()
  @Enumerated(EnumType.name)
  late InsightStatus status;

  // A processing request older than a few minutes means the app was closed
  // mid-request; treat it as failed so the user can try again.
  late DateTime requestedAt;

  // Filled in when status is complete.
  String? modelVersion;
  String? insightText; // At most 200 words, per the prompt

  @Enumerated(EnumType.name)
  BiasType? primaryBias; // Null when the model found none

  @Enumerated(EnumType.name)
  EmotionalTone? emotionalTone;

  @Enumerated(EnumType.name)
  RiskLevel? riskLevel;

  int? actionabilityScore; // 1–10
  String? suggestedAlternative;
  double? modelConfidence; // 0.0–1.0, drives the AI-limitations warning
  DateTime? generatedAt;
}
